// On-page content for the 10 tool pages.
//
// These pages previously shipped ~50 words of unique server-rendered text, so
// they could not rank for the queries they target ("step by step math solver",
// "free AI exam marking", …) even though they are the site's most valuable
// pages. This is real, server-rendered copy: how the tool works, how the output
// differs per exam board, a worked example, and FAQs.
//
// Plain text only — it is rendered directly, not through the markdown renderer.

export type ToolContent = {
  slug: string;
  intro: string;
  howItWorks: { step: string; text: string }[];
  boards: string;
  example: { title: string; body: string };
  tips: string[];
  faqs: { q: string; a: string }[];
};

